    print(f"\n{inp} -> {outp}")

    # Find minimal edit - let's do this manually
    # We'll look for the simplest pattern that explains the difference

    # Simplest approach: look for single character replacements
    if len(inp) == len(outp):
        # Same length - look for character substitutions
        for i in range(len(inp)):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
    else:
        # Different lengths - insertion/deletion
        print(f"  Length change: {len(inp)} -> {len(outp)}")

        # Try to identify what's being inserted/deleted
        min_len = min(len(inp), len(outp))
        for i in range(min_len):
            if inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")

        # Check for extra characters
        if len(outp) > len(inp):
            for i in range(len(inp), len(outp)):
                print(f"  Extra char at position {i}: '{outp[i]}'")
        elif len(inp) > len(outp):
            for i in range(len(outp), len(inp)):
                print(f"  Deleted char at position {i}: '{inp[i]}'")

